 try{$q=$pdo->prepare("INSERT INTO students (admission_no,full_name,class_name,section_name,date_of_birth,gender,guardian_name,guardian_phone,status) VALUES (?,?,?,?,?,?,?,?,?)");$q->execute([$data['admission_no'],$data['full_name'],$data['class_name'],$data['section_name'],$data['date_of_birth'],$data['gender'],$data['guardian_name'],$data['guardian_phone'],$data['status']]);flash('Student Management record saved.');go('students/index.php');}catch(Throwable $e){$error='Unable to save record. Check required fields and duplicate values.';}
}
