<h1>Student Management</h1><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif;?>
<div class="panel"><h2>Add new record</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid"><div><label>Admission number</label><input type="text" name="admission_no" required></div><div><label>Student full name</label><input type="text" name="full_name" required></div><div><label>Class</label><input type="text" name="class_name" ></div><div><label>Section</label><input type="text" name="section_name" ></div><div><label>Date of birth</label><input type="date" name="date_of_birth" ></div><div><label>Gender</label><select name="gender" required><option value="">Select</option><option value="Male">Male</option><option value="Female">Female</option><option value="Other">Other</option></select></div><div><label>Guardian name</label><input type="text" name="guardian_name" ></div><div><label>Guardian phone</label><input type="text" name="guardian_phone" ></div><div><label>Status</label><select name="status" required><option value="">Select</option><option value="active">active</option><option value="inactive">inactive</option><option value="graduated">graduated</option><option value="withdrawn">withdrawn</option></select></div></div><button>Save record</button></form></div>
<div class="panel"><h2>Records</h2><div class="tablewrap"><table><tr><th>Admission number</th><th>Student full name</th><th>Class</th><th>Section</th><th>Date of birth</th><th>Gender</th><th>Guardian name</th><th>Guardian phone</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r["admission_no"])?></td><td><?=h($r["full_name"])?></td><td><?=h($r["class_name"])?></td><td><?=h($r["section_name"])?></td><td><?=h($r["date_of_birth"])?></td><td><?=h($r["gender"])?></td><td><?=h($r["guardian_name"])?></td><td><?=h($r["guardian_phone"])?></td><td><?=h($r["status"])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9">No records found.</td></tr><?php endif;?></table></div></div>
